const { Matrix } = require('./s3_matrix.js');

// Test identity function
console.log("Testing static identity(n) function...");

try {
  // Test valid identity matrix
  const identity2 = Matrix.identity(2);
  console.log("Identity 2x2 matrix:");
  console.log(identity2.toArray());

  // Test another valid identity matrix
  const identity3 = Matrix.identity(3);
  console.log("Identity 3x3 matrix:");
  console.log(identity3.toArray());

  // Test invalid input - should throw error
  Matrix.identity(-1);
  console.log("ERROR: Should have thrown for negative n");
} catch (e) {
  console.log("Correctly threw error for negative n:", e.message);
}

try {
  Matrix.identity(0);
  console.log("ERROR: Should have thrown for zero n");
} catch (e) {
  console.log("Correctly threw error for zero n:", e.message);
}

try {
  Matrix.identity(2.5);
  console.log("ERROR: Should have thrown for non-integer n");
} catch (e) {
  console.log("Correctly threw error for non-integer n:", e.message);
}

try {
  Matrix.identity("5");
  console.log("ERROR: Should have thrown for string n");
} catch (e) {
  console.log("Correctly threw error for string n:", e.message);
}

console.log("\nTesting transpose() method...");

// Test transpose method
const matrix1 = new Matrix([[1, 2, 3], [4, 5, 6]]);
console.log("Original matrix:");
console.log(matrix1.toArray());

const transposed1 = matrix1.transpose();
console.log("Transposed matrix:");
console.log(transposed1.toArray());

// Test with a non-square matrix
const matrix2 = new Matrix([[1, 2], [3, 4], [5, 6]]);
console.log("Original 3x2 matrix:");
console.log(matrix2.toArray());

const transposed2 = matrix2.transpose();
console.log("Transposed 2x3 matrix:");
console.log(transposed2.toArray());

// Test that transpose of transpose equals original
const doubleTransposed = transposed1.transpose();
console.log("Double transposed (should equal original):");
console.log(doubleTransposed.toArray());

console.log("\nAll tests completed successfully!");

