const { Matrix } = require('./s3_matrix.js');

// Test identity method
console.log("Testing identity method...");
try {
  const identity2 = Matrix.identity(2);
  console.log("Identity 2x2 matrix:");
  console.log(identity2.rows);

  const identity3 = Matrix.identity(3);
  console.log("Identity 3x3 matrix:");
  console.log(identity3.rows);

  // Test error case
  try {
    Matrix.identity(-1);
    console.log("ERROR: Should have thrown for negative n");
  } catch (e) {
    console.log("Correctly threw error for negative n:", e.message);
  }

  try {
    Matrix.identity(2.5);
    console.log("ERROR: Should have thrown for non-integer n");
  } catch (e) {
    console.log("Correctly threw error for non-integer n:", e.message);
  }

  try {
    Matrix.identity("not a number");
    console.log("ERROR: Should have thrown for string n");
  } catch (e) {
    console.log("Correctly threw error for string n:", e.message);
  }

  console.log("Identity tests passed!");
} catch (e) {
  console.log("Identity test failed:", e.message);
}

// Test transpose method
console.log("\nTesting transpose method...");
try {
  const m1 = new Matrix([[1, 2, 3], [4, 5, 6]]);
  console.log("Original matrix:");
  console.log(m1.rows);

  const transposed = m1.transpose();
  console.log("Transposed matrix:");
  console.log(transposed.rows);

  // Verify the transpose is correct
  console.assert(transposed.get(0, 0) === 1, "Transpose failed");
  console.assert(transposed.get(0, 1) === 4, "Transpose failed");
  console.assert(transposed.get(1, 0) === 2, "Transpose failed");
  console.assert(transposed.get(1, 1) === 5, "Transpose failed");
  console.assert(transposed.get(2, 0) === 3, "Transpose failed");
  console.assert(transposed.get(2, 1) === 6, "Transpose failed");

  console.log("Transpose tests passed!");
} catch (e) {
  console.log("Transpose test failed:", e.message);
}

console.log("\nAll tests completed!");

